select s.id,s.name,s.recurrence_type,s.interval_value,s.status,s.next_run_at,i.quantity,p.name_ar as product,r.status as run_status,r.scheduled_for,r.order_id from subscriptions.customer_product_subscriptions s join subscriptions.customer_product_subscription_items i on i.subscription_id=s.id join catalog.products p on p.id=i.product_id left join subscriptions.customer_product_subscription_runs r on r.subscription_id=s.id where s.id='d5911ced-f7d8-495a-9227-5c132d171bab';
